        "Hlavná myšlienka: ab označuje začiatočný bod v čase, cene alebo priestore a znamená „od, počnúc“: ab Montag (od pondelka, počnúc pondelkom), ab 18 Uhr, ab 10 Euro.",
        "Predložka sa viaže s datívom: ab nächstem Monat, ab dem 1. Mai. Pri časových údajoch často stojí bez člena: ab Montag, ab morgen. Ab je aj odlučiteľná predpona: abfahren (odísť, odcestovať), abholen (vyzdvihnúť, prevziať).",
        "Na rozdiel od seit (od istého času v minulosti) sa ab pozerá dopredu alebo na konkrétny začiatočný bod, často v budúcnosti."
