      "explanation": [
        "Hlavná myšlienka: aus znamená „z, von z“ (zvnútra) a vyjadruje pôvod, materiál alebo príčinu: aus dem Haus (z domu), aus Lettland (z Lotyšska), aus Holz (z dreva).",
        "Predložka sa vždy viaže s datívom: aus dem Haus, aus der Stadt, aus einem Buch.",
        "Vo význame príčiny vyjadruje aus citový motív: aus Angst (zo strachu), aus Liebe (z lásky)."
      ],
      "examples": [
        {
          "de": "Ich komme aus Lettland.",
          "lv": "Som z Lotyšska."
        },
        {
          "de": "Er nimmt ein Heft aus der Tasche.",
          "lv": "Vyberá zošit z tašky."
        },
        {
          "de": "Der Tisch ist aus Holz.",
          "lv": "Stôl je z dreva."
        },
        {
          "de": "Sie schweigt aus Angst.",
          "lv": "Mlčí zo strachu."
        },
        {
          "de": "Der Zug aus Berlin hat Verspätung.",
          "lv": "Vlak z Berlína mešká."
        }
      ],
      "comparison": [
        {
          "word": "von",
          "meaning": "od (človeka, bodu)",
          "example": "Ich habe einen Brief von meiner Mutter. – Mám list od mamy."
        },
        {
          "word": "bei",
          "meaning": "pri, u",
          "example": "Ich bin bei meiner Oma. – Som u babky."
        },
        {
          "word": "nach",
          "meaning": "do (mesta)",
          "example": "Ich fahre nach Berlin. – Cestujem do Berlína."
        }
      ],
      "tip": [
        "Aus = „von zvnútra“: Auto, Haus, Tasche. Opakom je in.",
        "Pri pôvode z krajiny alebo mesta sa používa aus: Ich bin aus Riga."
      ],
      "important": [
        "Po aus je vždy datív, nikdy akuzatív.",
        "Človek, od ktorého niečo dostávaš, sa vyjadruje pomocou von: ein Brief von Anna, nie „aus Anna“."
      ],
