        "Množné číslo: die Männer (s prehláskou). Genitív: des Mannes, datív množného čísla: den Männern. V zloženinách: Ehemann, Geschäftsmann (množné číslo Geschäftsleute).",
        "Rozdiel oproti slovu man: man (človek, niekto všeobecne) je zámeno a píše sa s malým písmenom a jedným n. Človeka všeobecne označuje der Mensch."
