      "id": "a1-neu",
      "layout": "standardStudy",
      "translation": "nový",
      "explanation": [
        "Hlavná myšlienka: neu znamená „nový” o veciach a javoch, ktoré nedávno vznikli alebo boli kúpené: ein neues Handy, eine neue Wohnung, neue Schuhe. O veku človeka sa používa jung.",
        "Pred podstatným menom sa neu skloňuje: ein neuer Tisch, eine neue Jacke, ein neues Auto, neue Freunde. 2. stupeň: neuer, 3. stupeň: am neuesten. Po sein je bez koncovky: Mein Handy ist neu.",
        "O človeku znamená neu „ktorý nedávno prišiel, nový v práci alebo v triede”: ein neuer Kollege, eine neue Lehrerin."
      ],
      "examples": [
        {
          "de": "Mein Handy ist neu.",
          "lv": "Môj mobil je nový."
        },
        {
          "de": "Wir haben ein neues Auto.",
          "lv": "Máme nové auto."
        },
        {
          "de": "Das ist meine neue Wohnung.",
          "lv": "Toto je môj nový byt."
        },
        {
          "de": "Ich habe neue Schuhe gekauft.",
          "lv": "Kúpil som si nové topánky."
        },
        {
          "de": "Wir haben einen neuen Kollegen.",
          "lv": "Máme nového kolegu."
        }
      ],
      "comparison": [
        {
          "word": "jung",
          "meaning": "mladý (o človeku)",
          "example": "Meine Tante ist jung. – Moja teta je mladá."
        },
        {
          "word": "alt",
          "meaning": "starý",
          "example": "Das Haus ist alt. – Ten dom je starý."
        },
        {
          "word": "modern",
          "meaning": "moderný",
          "example": "Das Büro ist modern. – Kancelária je moderná."
        }
      ],
      "tip": [
        "Opozitá: neu ≠ alt (nový ≠ starý); jung ≠ alt (mladý ≠ starý, o človeku).",
        "Neu sa dá spájať: neu eröffnet (novootvorený), neu bauen (postaviť nanovo)."
      ],
      "important": [
        "O veku človeka sa zvyčajne hovorí jung, nie neu.",
        "Neu (nový) a neun (deväť) sú rôzne slová."
      ],
