      "layout": "standardStudy",
      "translation": "pod",
      "explanation": [
        "Hlavná myšlienka: unter je predložka so základným významom pod. Ak sa pýtame Wo?, nasleduje datív (Die Katze schläft unter dem Tisch), ak Wohin? — akuzatív (Er legt den Schlüssel unter die Zeitung).",
        "V prenesenom význame môže unter znamenať medzi (unter Freunden — medzi priateľmi), menej ako (unter 18 Jahren — pod 18 rokov) a pod niečím vplyvom alebo za istých okolností.",
        "Opakom je über (nad), ale blízko k miestu a povrchu je aj auf."
      ],
      "examples": [
        {
          "de": "Die Katze schläft unter dem Tisch.",
          "lv": "Mačka spí pod stolom."
        },
        {
          "de": "Er legt den Schlüssel unter die Zeitung.",
          "lv": "Položí kľúč pod noviny."
        },
        {
          "de": "Unter uns gesagt, ich mag ihn nicht.",
          "lv": "Medzi nami, nemám ho rád."
        },
        {
          "de": "Kinder unter sechs Jahren fahren kostenlos.",
          "lv": "Deti mladšie ako šesť rokov cestujú zadarmo."
        }
      ],
      "comparison": [
        {
          "word": "über",
          "meaning": "nad",
          "example": "Die Lampe hängt über dem Tisch. – Lampa visí nad stolom."
        },
        {
          "word": "zwischen",
          "meaning": "medzi",
          "example": "Der Stuhl steht zwischen Tisch und Tür. – Stolička stojí medzi stolom a dverami."
        },
        {
          "word": "hinter",
          "meaning": "za",
          "example": "Der Garten ist hinter dem Haus. – Záhrada je za domom."
        }
      ],
      "tip": [
        "Wo? — unter dem Tisch; Wohin? — unter den Tisch. Uč sa ju spolu s ostatnými predložkami s datívom aj akuzatívom.",
        "Fráza unter uns znamená „medzi nami” a používa sa, keď niečo hovoríme dôverne."
      ],
      "important": [
        "Unter nie je to isté ako zwischen: unter odkazuje na súbor alebo skupinu (unter Freunden), zwischen — na dve konkrétne veci.",
        "Unter + číslo znamená „menej ako”: unter 18 je mladší ako 18."
      ],
