        "Jednotlivé druhy zeleniny sa nazývajú vlastnými slovami: die Karotte, die Gurke, der Kohl. V textoch sa často používa frisches Gemüse, Gemüse kaufen, Gemüse anbauen.",
        "Protikladom je das Obst (ovocie) a obe slová sú v jednotnom čísle."
